const listPayments = `-- name: ListPayments :many
SELECT p.id, p.school_id, p.student_id, p.receipt_no, p.payment_date, p.payment_method, p.amount_minor, p.allocated_amount_minor, p.unallocated_amount_minor, p.reference_no, p.payer_name, p.payer_phone, p.status, p.recorded_by_id, p.recorded_at, p.notes, s.first_name AS student_first_name, s.last_name AS student_last_name, s.admission_no,
       u.display_name AS recorded_by_name
FROM payments p
JOIN students s ON p.student_id = s.id
JOIN users u ON p.recorded_by_id = u.id
WHERE p.school_id = ?
  AND (? = '' OR p.student_id = ?)
  AND (? = '' OR p.status = ?)
  AND (? = '' OR p.payment_method = ?)
ORDER BY p.recorded_at DESC
LIMIT ?
`

