const upsertCreditBalance = `-- name: UpsertCreditBalance :exec
INSERT INTO credit_balances (
    id, school_id, student_id, amount_minor, updated_at, created_at
) VALUES (?, ?, ?, ?, ?, ?)
ON CONFLICT (school_id, student_id)
DO UPDATE SET amount_minor = excluded.amount_minor, updated_at = excluded.updated_at
`

type UpsertCreditBalanceParams struct {
	ID          string `json:"id"`
	SchoolID    string `json:"school_id"`
	StudentID   string `json:"student_id"`
	AmountMinor int64  `json:"amount_minor"`
	UpdatedAt   string `json:"updated_at"`
	CreatedAt   string `json:"created_at"`
}

func (q *Queries) UpsertCreditBalance(ctx context.Context, arg UpsertCreditBalanceParams) error {
	_, err := q.db.ExecContext(ctx, upsertCreditBalance,
		arg.ID,
		arg.SchoolID,
		arg.StudentID,
		arg.AmountMinor,
		arg.UpdatedAt,
		arg.CreatedAt,
	)
	return err
}
